<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>2048</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    background: #1a1a2e;
    color: #eee;
    font-family: Arial, sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
  }
  h1 { font-size: 3rem; margin-bottom: 16px; color: #f0c040; }
  .header {
    display: flex;
    align-items: center;
    gap: 24px;
    margin-bottom: 16px;
  }
  #score {
    background: #16213e;
    border: 2px solid #0f3460;
    padding: 8px 20px;
    border-radius: 8px;
    font-size: 1.2rem;
    font-weight: bold;
    min-width: 120px;
    text-align: center;
  }
  #reset {
    background: #e94560;
    color: #fff;
    border: none;
    padding: 10px 22px;
    border-radius: 8px;
    font-size: 1rem;
    font-weight: bold;
    cursor: pointer;
    transition: background 0.2s;
  }
  #reset:hover { background: #c73652; }
  #board {
    background: #0f3460;
    border-radius: 10px;
    padding: 10px;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 10px;
    width: 360px;
    height: 360px;
  }
  .tile {
    border-radius: 6px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.6rem;
    font-weight: bold;
    background: #16213e;
    color: #ccc;
    transition: background 0.1s;
  }
  .tile[data-val="0"]   { background: #16213e; color: transparent; }
  .tile[data-val="2"]   { background: #4a9eff; color: #fff; }
  .tile[data-val="4"]   { background: #3a7bd5; color: #fff; }
  .tile[data-val="8"]   { background: #f0823c; color: #fff; }
  .tile[data-val="16"]  { background: #e94560; color: #fff; }
  .tile[data-val="32"]  { background: #c0392b; color: #fff; }
  .tile[data-val="64"]  { background: #e67e22; color: #fff; }
  .tile[data-val="128"] { background: #f1c40f; color: #fff; font-size: 1.3rem; }
  .tile[data-val="256"] { background: #2ecc71; color: #fff; font-size: 1.3rem; }
  .tile[data-val="512"] { background: #1abc9c; color: #fff; font-size: 1.2rem; }
  .tile[data-val="1024"]{ background: #9b59b6; color: #fff; font-size: 1rem; }
  .tile[data-val="2048"]{ background: #f0c040; color: #1a1a2e; font-size: 1rem; }
</style>
</head>
<body>
<h1>2048</h1>
<div class="header">
  <div id="score">Score: 0</div>
  <button id="reset">New Game</button>
</div>
<div id="board"></div>
<script>
(function() {
  const SIZE = 4;
  let grid = [];
  let currentScore = 0;

  function newGrid() {
    return Array.from({length: SIZE}, () => Array(SIZE).fill(0));
  }

  function emptyCell(g) {
    const cells = [];
    for (let r = 0; r < SIZE; r++)
      for (let c = 0; c < SIZE; c++)
        if (g[r][c] === 0) cells.push([r, c]);
    return cells;
  }

  function spawnTile(g) {
    const cells = emptyCell(g);
    if (!cells.length) return;
    const [r, c] = cells[Math.floor(Math.random() * cells.length)];
    g[r][c] = Math.random() < 0.9 ? 2 : 4;
  }

  function slideRow(row) {
    // compress non-zeros left
    let arr = row.filter(v => v !== 0);
    let score = 0;
    for (let i = 0; i < arr.length - 1; i++) {
      if (arr[i] === arr[i + 1]) {
        arr[i] *= 2;
        score += arr[i];
        arr.splice(i + 1, 1);
      }
    }
    while (arr.length < SIZE) arr.push(0);
    return { row: arr, score };
  }

  function applyMove(dir) {
    let moved = false;
    let gained = 0;

    if (dir === 'left') {
      for (let r = 0; r < SIZE; r++) {
        const { row, score } = slideRow(grid[r].slice());
        if (row.join() !== grid[r].join()) moved = true;
        grid[r] = row;
        gained += score;
      }
    } else if (dir === 'right') {
      for (let r = 0; r < SIZE; r++) {
        const { row, score } = slideRow(grid[r].slice().reverse());
        const newRow = row.reverse();
        if (newRow.join() !== grid[r].join()) moved = true;
        grid[r] = newRow;
        gained += score;
      }
    } else if (dir === 'up') {
      for (let c = 0; c < SIZE; c++) {
        const col = grid.map(r => r[c]);
        const { row, score } = slideRow(col);
        for (let r = 0; r < SIZE; r++) {
          if (grid[r][c] !== row[r]) moved = true;
          grid[r][c] = row[r];
        }
        gained += score;
      }
    } else if (dir === 'down') {
      for (let c = 0; c < SIZE; c++) {
        const col = grid.map(r => r[c]).reverse();
        const { row, score } = slideRow(col);
        const newCol = row.reverse();
        for (let r = 0; r < SIZE; r++) {
          if (grid[r][c] !== newCol[r]) moved = true;
          grid[r][c] = newCol[r];
        }
        gained += score;
      }
    }

    if (moved) {
      currentScore += gained;
      spawnTile(grid);
      render();
    }
    return moved;
  }

  function render() {
    document.getElementById('score').textContent = 'Score: ' + currentScore;
    const board = document.getElementById('board');
    const tiles = board.querySelectorAll('.tile');
    let i = 0;
    for (let r = 0; r < SIZE; r++) {
      for (let c = 0; c < SIZE; c++) {
        const v = grid[r][c];
        tiles[i].textContent = v === 0 ? '' : v;
        tiles[i].setAttribute('data-val', v);
        i++;
      }
    }
  }

  function initDOM() {
    const board = document.getElementById('board');
    board.innerHTML = '';
    for (let i = 0; i < SIZE * SIZE; i++) {
      const div = document.createElement('div');
      div.className = 'tile';
      div.setAttribute('data-val', '0');
      board.appendChild(div);
    }
  }

  function resetGame() {
    grid = newGrid();
    currentScore = 0;
    spawnTile(grid);
    spawnTile(grid);
    render();
  }

  document.getElementById('reset').addEventListener('click', resetGame);

  document.addEventListener('keydown', e => {
    const map = {
      ArrowLeft: 'left', ArrowRight: 'right',
      ArrowUp: 'up', ArrowDown: 'down'
    };
    if (map[e.key]) {
      e.preventDefault();
      applyMove(map[e.key]);
    }
  });

  window.game = {
    size: SIZE,
    reset() { resetGame(); },
    move(dir) { return applyMove(dir); },
    board() { return grid.map(r => r.slice()); },
    setBoard(arr) {
      grid = arr.map(r => r.slice());
      render();
    },
    score() { return currentScore; }
  };

  initDOM();
  resetGame();
})();
</script>
</body>
</html>
